Given a number n, generate all binary numbers with decimal values from 1 to n.Examples:Input: n = 4Output: ["1", "10", "11", "100"]Explanation: Binary numbers from 1 to 4 are 1, 10, 11 and 100.Input: n = 6Output: ["1", "10", "11", "100", "101", "110"]Explanation: Binary numbers from 1 to 6 are 1, 10, 11, 100, 101 and 110.Try It YourselfTable of Content[Naive Approach] Using Bit Manipulation - O(n log(n)) Time and O(1) Space[Expected Approach] Using Queue - O(n) Time and O(n) Space[Naive Approach] Using Bit Manipulation - O(n log(n)) Time and O(1) SpaceThe idea is to traverse for all numbers from 1 to n and generate their binary representations. 
            C++

    #include <iostream>
#include <vector>
#include <algorithm> 

using namespace std;

vector<string> generateBinary(int n) {
    vector<string> result;

    for (int num = 1; num <= n; num++) {
        int temp = num;
        string binary = "";

        // Convert decimal number to binary
        while (temp > 0) {
            int rem = temp % 2;

            if (rem == 0)
                binary += "0"; 
            else
                binary += "1"; 

            temp = temp / 2;
        }

        // reverse to get correct order
        reverse(binary.begin(), binary.end()); 

        result.push_back(binary);
    }

    return result;
}

int main() {
    int n = 6;
    vector<string> binaries = generateBinary(n);

    for (auto bin : binaries)
        cout << bin << " ";
    cout << endl;

    return 0;
}


